// Normalise whatever the transport sends into one shape.
// Cloud API, Twilio and an unofficial bridge all post different bodies; every
// node downstream depends only on the three fields below, so swapping the
// transport means editing this node and nothing else.
const b = $json.body ?? $json;

// WhatsApp Cloud API
const cloud = b?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
const cloudFrom = cloud?.from;
const cloudText = cloud?.text?.body;
const cloudName = b?.entry?.[0]?.changes?.[0]?.value?.contacts?.[0]?.profile?.name;

// Twilio
const twilioFrom = b?.From && String(b.From).replace('whatsapp:', '');
const twilioText = b?.Body;
const twilioName = b?.ProfileName;

// Plain JSON (an unofficial bridge, or curl while testing)
const plainFrom = b?.from ?? b?.phone;
const plainText = b?.text ?? b?.message;
const plainName = b?.name;

const from = cloudFrom ?? twilioFrom ?? plainFrom ?? '';
const text = (cloudText ?? twilioText ?? plainText ?? '').trim();
const name = cloudName ?? twilioName ?? plainName ?? '';

if (!from || !text) {
  // Delivery receipts and status callbacks land here too — ignore them quietly.
  return [];
}

return [{ json: { from, text, name, receivedAt: new Date().toISOString() } }];

// Seats, and the prompt that goes with them.
//
// A seat is taken by anyone CONFIRMED, and also by anyone still PENDING inside
// the hold window: a pending registration is a seat someone is on their way to
// paying for. Counting only confirmed rows would let the agent promise seats
// that are already spoken for, and the course would oversell.
//
// A pending row older than the window releases its seat on its own — no cleanup
// job needed, because the count is derived rather than stored.
const HOLD_HOURS = 48;
const TOTAL_SEATS = 30;

const inbound = $('Normalise payload').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && (r.status || r.phone));

// The sheet read is allowed to fail (onError: continue). If it did, we must not
// invent a number — `seats` stays null and the agent is told to omit it.
const sheetOk = rows.length > 0 || $input.all().length > 0;

let seats = null;
if (sheetOk) {
  const now = Date.now();
  const taken = rows.filter((r) => {
    const status = String(r.status ?? '').toLowerCase();
    if (status === 'confirmed') return true;
    if (status !== 'pending') return false;
    const created = Date.parse(r.createdAt ?? '');
    if (Number.isNaN(created)) return true; // undated pending: treat as held
    return now - created < HOLD_HOURS * 3600 * 1000;
  }).length;
  seats = Math.max(0, TOTAL_SEATS - taken);
}

const seatLine =
  seats === null
    ? 'SEATS: unavailable — do NOT mention seats at all in your reply.'
    : `SEATS: ${seats} of ${TOTAL_SEATS} still available.`;

return [{ json: { ...inbound, seats, totalSeats: TOTAL_SEATS, seatLine } }];

