// The whole prompt in one place.
//
// Paste the contents of course-agent-knowledge.md into KNOWLEDGE below. It is
// inlined rather than fetched so the agent cannot answer from a stale or
// half-loaded copy — the knowledge either ships with the workflow or it does
// not run.
const KNOWLEDGE = `PASTE course-agent-knowledge.md HERE`;

const d = $json;

const system = `أنت مساعد تسجيل لكورس «AI in Software Testing» من Zyndesk، تردّ على واتساب.

${d.seatLine}

أجب حصراً من قاعدة المعرفة التالية. أي شيء غير موجود فيها، قل إنك ستتحقق وحوّل
للتواصل المباشر على 0797700235. لا تخترع شيئاً أبداً.

أعِد JSON فقط بهذا الشكل، بلا أي نص خارجه:
{
  "reply": "ردّك للطالب",
  "intent": "info" | "register" | "payment" | "other",
  "lead": { "name": "", "phone": "", "email": "" } أو null
}

قواعد النية:
- intent = "register" فقط عندما يطلب الطالب التسجيل صراحةً.
- عند طلب التسجيل، لا تُعِد شرح الكورس. اطلب مباشرةً: الاسم الكامل، رقم الهاتف،
  الإيميل.
- املأ "lead" فقط عندما تكون الحقول الثلاثة قد وصلتك فعلاً. إن نقص أيها،
  اجعل lead = null واطلب الناقص فقط.
- لا تطلب أبداً بيانات بطاقة أو حساب بنكي.

قاعدة المعرفة:
${KNOWLEDGE}`;

return [{ json: { ...d, system } }];

// Parse the model's JSON, and never let a bad parse become a silent failure.
const raw = $json.choices?.[0]?.message?.content ?? '';
const inbound = $('Compute seats').first().json;

let parsed;
try {
  parsed = JSON.parse(raw);
} catch {
  parsed = {
    reply: 'عذراً، صار خلل بسيط. تواصل معنا مباشرة على 0797700235 وبنساعدك فوراً.',
    intent: 'other',
    lead: null,
  };
}

const lead = parsed.lead;
const complete = Boolean(lead?.name && lead?.phone && lead?.email);

return [{
  json: {
    ...inbound,
    reply: parsed.reply ?? '',
    intent: parsed.intent ?? 'other',
    lead: complete ? lead : null,
    hasLead: complete,
  },
}];

