// Meta verifies a webhook before it will ever deliver to it: it sends a GET
// with hub.mode, hub.verify_token and hub.challenge, and expects the challenge
// echoed back as plain text.
//
// The token check matters. Without it, anyone who guessed this URL could point
// their own WhatsApp app at your workflow.
const q = $json.query ?? {};
const expected = $env.WHATSAPP_VERIFY_TOKEN;

if (!expected) {
  throw new Error("WHATSAPP_VERIFY_TOKEN is not set on the n8n server");
}
if (q["hub.mode"] !== "subscribe" || q["hub.verify_token"] !== expected) {
  throw new Error("verify token mismatch");
}

return [{ json: { challenge: q["hub.challenge"] } }];
